/* ---------- 2. COD verification + risk score ---------- */
X.codRisk=function(o){var s=0,why=[],v=(o.ship&&o.ship.vals)||{},ph=String(v.Phone||v['Phone number']||o.phone||'').replace(/\D/g,'');
 if(!/^(92|0)?3\d{9}$/.test(ph)){s+=35;why.push('Phone is not a valid Pakistani mobile')}
 if(o.total>300){s+=20;why.push('High order value')}else if(o.total>100){s+=10;why.push('Medium order value')}
 var prev=(S.orders||[]).filter(function(x){return x.email===o.email&&x.id!==o.id});var bad=prev.filter(function(x){return x.cancelled||x.rto}).length;if(bad){s+=25*Math.min(bad,2);why.push(bad+' previous cancelled/returned order(s)')}
 if(!prev.length){s+=10;why.push('First-time customer')}
 var addr=JSON.stringify((o.ship&&o.ship.addr)||'');if(addr.length<25){s+=15;why.push('Short or missing address')}
 if(['test','fake','asdf'].some(function(b){return String(o.who||'').toLowerCase().indexOf(b)>-1})){s+=20;why.push('Suspicious name')}
 s=Math.max(0,Math.min(100,s));return {score:s,level:s>=60?'High':s>=30?'Medium':'Low',why:why}};
function codOrders(){return (S.orders||[]).filter(function(o){return o.cod||/cash on delivery|\bcod\b/i.test(o.gw||'')})}
V['plus-cod']=function(){var p=P(),L=codOrders();
 return '<div class="xw">'+hd('COD verification',btn('Verify all low-risk','m9codall:'))+'<p class="mu">Every cash-on-delivery order gets a 0–100 risk score. Confirm risky orders by WhatsApp/SMS OTP before booking a courier.</p>'+card('Cash-on-delivery orders',tbl(['Order','Customer','Total','Risk','Reasons','Verification',''],L.map(function(o){var r=X.codRisk(o),v=(p.cod.filter(function(c){return c.oid===o.id})[0]||{});return tr(['<a href="#order-'+o.id+'">#'+o.id+'</a>',h(o.who),money9(o.total),pill(r.level+' · '+r.score,r.level==='High'?'bad':r.level==='Medium'?'warn':'ok'),'<span class="xk">'+h(r.why.join('; ')||'—')+'</span>',pill(v.status||'Unverified',v.status==='Verified'?'ok':v.status==='Rejected'?'bad':''),(v.status==='Verified'||v.status==='Rejected')?'':btn('Send OTP','m9codotp:'+o.id)+' '+btn('Verify','m9codok:'+o.id,1)+' '+btn('Reject','m9codno:'+o.id)])}),'No cash-on-delivery orders yet. WhatsApp orders and COD checkouts appear here.'))+'</div>'};
function codSet(id,st,extra){var p=P(),c=p.cod.filter(function(x){return x.oid===+id})[0];if(!c){c={oid:+id};p.cod.push(c)}c.status=st;c.at=Date.now();Object.assign(c,extra||{});return c}
X.m9codSet=codSet;
