X.m9reconcile=function(csv){var rows=String(csv||'').split(/\n/).map(function(l){return l.split(',').map(function(x){return x.trim()})}).filter(function(r){return r[0]&&!/^cn$/i.test(r[0])});var res={matched:0,mismatch:[],unknown:[]};
 rows.forEach(function(r){var s=shp(r[0]),amt=Number(r[1]);if(!s){res.unknown.push(r[0]);return}if(r[1]===undefined||r[1]===''||!isFinite(amt)){res.mismatch.push(r[0]+' (invalid amount)');return}var exp=s.cod-s.fee;if(Math.abs(amt-exp)>1){res.mismatch.push(r[0]+' (expected '+exp+', got '+amt+')');return}s.status='COD reconciled';s.settled=amt;res.matched++});sv();return res};
