var CURS=['PKR','USD','EUR','GBP','AED','SAR','CAD','AUD'];
X.roundPrice=function(v,rule){v=Number(v);if(!isFinite(v)||v<0)return 0;if(rule==='99')return Math.max(.99,Math.floor(v)+.99);if(rule==='5')return Math.ceil(v/5)*5;if(rule==='10')return Math.ceil(v/10)*10;if(rule==='100')return Math.ceil(v/100)*100;if(rule==='int')return Math.round(v);return Math.round(v*100)/100};
X.priceIn=function(pid,cur){var p=pr(pid);if(!p)return null;var f=(P().fx[pid]||{})[cur];if(f>0)return {v:f,fixed:true};var r=(S.rates||{})[cur]||1;return {v:X.roundPrice(p.price*r,P().cfg.round),fixed:false}};
